from __future__ import annotations

from datetime import datetime, timezone, timedelta

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.queries import TaskPage, TaskQuery, TaskQueryError, apply_query


NOW = datetime(2025, 6, 15, 12, 0, 0, tzinfo=timezone.utc)


def _make_task(id, title="Task", status=TaskStatus.PENDING, priority=TaskPriority.MEDIUM,
               due_at=None, tags=None, created_at=None):
    return Task(
        id=id,
        title=title,
        status=status,
        priority=priority,
        due_at=due_at,
        tags=tags or [],
        created_at=created_at or NOW - timedelta(hours=id),
    )


class TestTaskQueryValidation:
    def test_default_query_is_valid(self):
        q = TaskQuery()
        assert q.limit == 20
        assert q.offset == 0
        assert q.sort == "created_at"

    @pytest.mark.parametrize("field", ["created_at", "due_at", "priority", "title"])
    def test_valid_sort_fields(self, field):
        q = TaskQuery(sort=field)
        assert q.sort == field

    def test_invalid_sort_raises(self):
        with pytest.raises(TaskQueryError):
            TaskQuery(sort="invalid")

    @pytest.mark.parametrize("limit", [0, -1, 101, "bad"])
    def test_invalid_limit_raises(self, limit):
        with pytest.raises(TaskQueryError):
            TaskQuery(limit=limit)

    def test_negative_offset_raises(self):
        with pytest.raises(TaskQueryError):
            TaskQuery(offset=-1)

    def test_tag_is_normalized(self):
        q = TaskQuery(tag="  FOO  ")
        assert q.tag == "foo"

    def test_invalid_tag_raises(self):
        with pytest.raises((TaskQueryError, ValueError)):
            TaskQuery(tag="bad char!")

    def test_blank_search_becomes_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None


class TestApplyQueryFiltering:
    @pytest.fixture
    def tasks(self):
        return [
            _make_task(1, "Buy milk", status=TaskStatus.PENDING, tags=[Tag("groceries")]),
            _make_task(2, "Read book", status=TaskStatus.DONE, tags=[Tag("leisure")]),
            _make_task(3, "Milk the cow", status=TaskStatus.PENDING,
                       due_at=NOW - timedelta(hours=2), tags=[Tag("farm")]),
        ]

    def test_filter_by_status(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.DONE), NOW)
        assert len(page.items) == 1
        assert page.items[0].id == 2

    def test_filter_by_tag(self, tasks):
        page = apply_query(tasks, TaskQuery(tag="groceries"), NOW)
        assert len(page.items) == 1
        assert page.items[0].id == 1

    def test_search_in_title(self, tasks):
        page = apply_query(tasks, TaskQuery(search="milk"), NOW)
        assert len(page.items) == 2
        ids = {t.id for t in page.items}
        assert ids == {1, 3}

    def test_filter_overdue_true(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=True), NOW)
        assert len(page.items) == 1
        assert page.items[0].id == 3

    def test_filter_overdue_false(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=False), NOW)
        # task 1 (no due) and task 2 (done) are not overdue
        ids = {t.id for t in page.items}
        assert 3 not in ids

    def test_combined_filters(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.PENDING, search="milk"), NOW)
        assert len(page.items) == 2


class TestApplyQuerySorting:
    @pytest.fixture
    def tasks(self):
        return [
            _make_task(1, "Banana", priority=TaskPriority.LOW,
                       created_at=NOW - timedelta(hours=3)),
            _make_task(2, "Apple", priority=TaskPriority.HIGH,
                       created_at=NOW - timedelta(hours=1)),
            _make_task(3, "Cherry", priority=TaskPriority.MEDIUM,
                       created_at=NOW - timedelta(hours=2),
                       due_at=NOW + timedelta(days=1)),
        ]

    def test_sort_by_title(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="title"), NOW)
        titles = [t.title for t in page.items]
        assert titles == ["Apple", "Banana", "Cherry"]

    def test_sort_by_title_descending(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="title", descending=True), NOW)
        titles = [t.title for t in page.items]
        assert titles == ["Cherry", "Banana", "Apple"]

    def test_sort_by_priority(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="priority"), NOW)
        priorities = [t.priority for t in page.items]
        assert priorities == [TaskPriority.HIGH, TaskPriority.MEDIUM, TaskPriority.LOW]

    def test_sort_by_created_at(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="created_at"), NOW)
        ids = [t.id for t in page.items]
        assert ids == [1, 3, 2]  # oldest first

    def test_sort_by_due_at_none_last(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="due_at"), NOW)
        # task 3 has a due_at, tasks 1 and 2 have None → sort last
        assert page.items[0].id == 3


class TestApplyQueryPagination:
    @pytest.fixture
    def tasks(self):
        return [_make_task(i, f"Task {i}") for i in range(1, 11)]

    def test_limit(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=3), NOW)
        assert len(page.items) == 3
        assert page.total == 10

    def test_offset(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=3, offset=8), NOW)
        assert len(page.items) == 2
        assert page.total == 10

    def test_has_more_true(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=5, offset=0), NOW)
        assert page.has_more is True

    def test_has_more_false(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=5, offset=5), NOW)
        assert page.has_more is False

    def test_offset_beyond_total(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=5, offset=20), NOW)
        assert page.items == []
        assert page.total == 10

